import java.util.Properties

plugins {
    id("com.android.application")
    id("org.jetbrains.kotlin.android")
}

// Pins and host are generated by scripts/gen_certs.sh
val pinProps = Properties().apply {
    rootProject.file("pins.properties").inputStream().use { load(it) }
}
fun quoted(key: String) = "\"" + pinProps.getProperty(key) + "\""

android {
    namespace = "com.example.sslpinning"
    compileSdk = 35

    defaultConfig {
        applicationId = "com.example.sslpinning"
        minSdk = 24 // Network Security Config requires API 24+
        targetSdk = 35
        versionCode = 1
        versionName = "1.0"

        buildConfigField("String", "TEST_HOST", quoted("testHost"))
        buildConfigField("int", "TEST_PORT", pinProps.getProperty("testPort"))
        buildConfigField("String", "PIN_A", quoted("pinA"))
        buildConfigField("String", "PIN_B", quoted("pinB"))
        buildConfigField("String", "PIN_C", quoted("pinC"))
    }

    buildFeatures { buildConfig = true }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
    kotlinOptions { jvmTarget = "17" }
}

dependencies {
    implementation("com.squareup.okhttp3:okhttp:4.12.0")
}
